import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.BbQrW5_t.js";const q=JSON.parse('{"title":"电子书读书笔记框架说明","description":"","frontmatter":{},"headers":[],"relativePath":"study/reading-notes/笔记框架说明.md","filePath":"study/reading-notes/笔记框架说明.md","lastUpdated":1786698794000}'),l={name:"study/reading-notes/笔记框架说明.md"};function i(h,a,d,n,s,u){return e(),r("div",null,[...a[0]||(a[0]=[o(`<h1 id="电子书读书笔记框架说明" tabindex="-1">电子书读书笔记框架说明 <a class="header-anchor" href="#电子书读书笔记框架说明" aria-label="Permalink to &quot;电子书读书笔记框架说明&quot;">​</a></h1><blockquote><p>版本：1.3.0 | 更新时间：2026-08-14</p></blockquote><hr><h2 id="五模块框架概览" tabindex="-1">五模块框架概览 <a class="header-anchor" href="#五模块框架概览" aria-label="Permalink to &quot;五模块框架概览&quot;">​</a></h2><p>采用&quot;系统论&quot;和&quot;认知心理学&quot;视角深度萃取，共五个模块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一、核心观点与逻辑骨架（含全书概览+章节速览+逐章详解）</span></span>
<span class="line"><span>二、认知升维与碰撞（四维映射）</span></span>
<span class="line"><span>三、专属建议生成（四轨并行）</span></span>
<span class="line"><span>四、行动计划（三级火箭）</span></span>
<span class="line"><span>五、跨界联想与质疑</span></span></code></pre></div><hr><h2 id="一、📌-核心观点与逻辑骨架" tabindex="-1">一、📌 核心观点与逻辑骨架 <a class="header-anchor" href="#一、📌-核心观点与逻辑骨架" aria-label="Permalink to &quot;一、📌 核心观点与逻辑骨架&quot;">​</a></h2><h3 id="_1-1-全书概览" tabindex="-1">1.1 全书概览 <a class="header-anchor" href="#_1-1-全书概览" aria-label="Permalink to &quot;1.1 全书概览&quot;">​</a></h3><p><strong>书籍定位</strong>：所属领域、目标读者、写作背景</p><p><strong>全书总结</strong>：用200-300字概括全书核心主题和作者意图</p><h3 id="_1-2-章节速览-按章节顺序" tabindex="-1">1.2 章节速览（按章节顺序） <a class="header-anchor" href="#_1-2-章节速览-按章节顺序" aria-label="Permalink to &quot;1.2 章节速览（按章节顺序）&quot;">​</a></h3><p>首先用表格概括全书章节结构：</p><table tabindex="0"><thead><tr><th>章节</th><th>核心主题</th><th>关键结论</th></tr></thead><tbody><tr><td>第1章</td><td>章节主题</td><td>核心论点</td></tr><tr><td>第2章</td><td>...</td><td>...</td></tr><tr><td>第3章</td><td>...</td><td>...</td></tr><tr><td>...</td><td>...</td><td>...</td></tr></tbody></table><p>然后逐章详细描述每章内容，让读者真正理解每章讲了什么：</p><hr><p><strong>第1章：章节名称</strong></p><p>本章主要讲述了......（具体内容概括，300-500字）</p><p>核心要点：</p><ul><li>要点一</li><li>要点二</li><li>要点三</li></ul><hr><p><strong>第2章：章节名称</strong></p><p>本章主要讲述了......（具体内容概括，300-500字）</p><p>核心要点：</p><ul><li>要点一</li><li>要点二</li><li>要点三</li></ul><hr><p>（后续章节依此类推）</p><p><strong>注意</strong>：</p><ul><li>每章内容概括控制在300-500字</li><li>对于章节较多的书籍（如30章以上），可按逻辑单元合并描述，但每个单元仍需详细说明核心内容</li><li>章节名称使用书中的实际章节标题</li></ul><h3 id="_1-3-核心论点" tabindex="-1">1.3 核心论点 <a class="header-anchor" href="#_1-3-核心论点" aria-label="Permalink to &quot;1.3 核心论点&quot;">​</a></h3><h4 id="一句话概括" tabindex="-1">一句话概括 <a class="header-anchor" href="#一句话概括" aria-label="Permalink to &quot;一句话概括&quot;">​</a></h4><p>用精炼的语言（不超过300字）概括全书核心。</p><h4 id="核心论点" tabindex="-1">核心论点 <a class="header-anchor" href="#核心论点" aria-label="Permalink to &quot;核心论点&quot;">​</a></h4><p>按文本理解罗列核心论点，不限制条数：</p><ol><li>论点一：展开2-3句说明</li><li>论点二：展开2-3句说明 ...（根据实际内容增减）</li></ol><h4 id="逻辑模型" tabindex="-1">逻辑模型 <a class="header-anchor" href="#逻辑模型" aria-label="Permalink to &quot;逻辑模型&quot;">​</a></h4><p>描述底层逻辑链条：因为A→导致B→为了解决B提出C→实施C的关键是D</p><h4 id="启发思考的5个点" tabindex="-1">启发思考的5个点 <a class="header-anchor" href="#启发思考的5个点" aria-label="Permalink to &quot;启发思考的5个点&quot;">​</a></h4><p>书中引发深度思考的观点或问题，每个点包含：问题引入 + 核心洞察 + 反思指引</p><p>模板：</p><ol><li><strong>问题引入</strong>？洞察。反思：具体问题</li><li>...</li><li>...</li><li>...</li><li>...</li></ol><hr><h2 id="二、💡-认知升维与碰撞" tabindex="-1">二、💡 认知升维与碰撞 <a class="header-anchor" href="#二、💡-认知升维与碰撞" aria-label="Permalink to &quot;二、💡 认知升维与碰撞&quot;">​</a></h2><h3 id="反直觉洞察" tabindex="-1">反直觉洞察 <a class="header-anchor" href="#反直觉洞察" aria-label="Permalink to &quot;反直觉洞察&quot;">​</a></h3><p>书中哪个观点颠覆了常规认知？对个人发展有哪些思维冲击？</p><h3 id="多维映射" tabindex="-1">多维映射 <a class="header-anchor" href="#多维映射" aria-label="Permalink to &quot;多维映射&quot;">​</a></h3><h4 id="映射到职业发展" tabindex="-1">映射到职业发展 <a class="header-anchor" href="#映射到职业发展" aria-label="Permalink to &quot;映射到职业发展&quot;">​</a></h4><p>将本书核心逻辑映射到职业发展（职业路径、技能提升、职场晋升），分析可能产生的&quot;涟漪效应&quot;或&quot;意外副作用&quot;。</p><h4 id="映射到创业与个人发展" tabindex="-1">映射到创业与个人发展 <a class="header-anchor" href="#映射到创业与个人发展" aria-label="Permalink to &quot;映射到创业与个人发展&quot;">​</a></h4><p>将本书核心逻辑映射到创业与个人发展（创业思考、副业探索、个人成长），分析可能产生的&quot;涟漪效应&quot;或&quot;意外副作用&quot;。</p><h4 id="映射到家庭教育" tabindex="-1">映射到家庭教育 <a class="header-anchor" href="#映射到家庭教育" aria-label="Permalink to &quot;映射到家庭教育&quot;">​</a></h4><p>将本书核心逻辑映射到家庭教育（特别是应对孩子畏难情绪及智力培养），分析可能产生的&quot;涟漪效应&quot;或&quot;意外副作用&quot;。</p><h4 id="映射到人生思考与感悟" tabindex="-1">映射到人生思考与感悟 <a class="header-anchor" href="#映射到人生思考与感悟" aria-label="Permalink to &quot;映射到人生思考与感悟&quot;">​</a></h4><p>将本书核心逻辑映射到人生思考与感悟（人生意义、价值观、生活态度），分析可能产生的&quot;涟漪效应&quot;或&quot;意外副作用&quot;。</p><hr><h2 id="三、🎯-专属建议生成-四轨并行" tabindex="-1">三、🎯 专属建议生成（四轨并行） <a class="header-anchor" href="#三、🎯-专属建议生成-四轨并行" aria-label="Permalink to &quot;三、🎯 专属建议生成（四轨并行）&quot;">​</a></h2><h3 id="路线a-职业发展-2-3条建议" tabindex="-1">路线A：职业发展（2-3条建议） <a class="header-anchor" href="#路线a-职业发展-2-3条建议" aria-label="Permalink to &quot;路线A：职业发展（2-3条建议）&quot;">​</a></h3><p><strong>建议一：标题 🔴🔴🔴</strong> 结合17年技术背景，给出具体职业发展建议（职业路径、技能提升、职场晋升等）。</p><p><strong>建议二：标题 🔴🔴</strong> 具体建议内容。</p><h3 id="路线b-创业与个人发展-2-3条建议" tabindex="-1">路线B：创业与个人发展（2-3条建议） <a class="header-anchor" href="#路线b-创业与个人发展-2-3条建议" aria-label="Permalink to &quot;路线B：创业与个人发展（2-3条建议）&quot;">​</a></h3><p><strong>建议一：标题 🔴🔴🔴</strong> 结合转型思考，给出具体创业或副业建议。</p><p><strong>建议二：标题 🔴🔴</strong> 具体建议内容。</p><h3 id="路线c-家庭教育-2-3条建议" tabindex="-1">路线C：家庭教育（2-3条建议） <a class="header-anchor" href="#路线c-家庭教育-2-3条建议" aria-label="Permalink to &quot;路线C：家庭教育（2-3条建议）&quot;">​</a></h3><p><strong>建议一：标题 🔴🔴🔴</strong> 结合两个孩子父亲背景（三年级女儿畏难/人际关系），给出具体教育或亲子互动建议。</p><p><strong>建议二：标题 🔴🔴</strong> 具体建议内容。</p><h3 id="路线d-人生思考与感悟-2-3条建议" tabindex="-1">路线D：人生思考与感悟（2-3条建议） <a class="header-anchor" href="#路线d-人生思考与感悟-2-3条建议" aria-label="Permalink to &quot;路线D：人生思考与感悟（2-3条建议）&quot;">​</a></h3><p><strong>建议一：标题 🔴🔴🔴</strong> 结合书中观点，给出人生感悟建议（人生意义、价值观、生活态度等）。</p><p><strong>建议二：标题 🔴🔴</strong> 具体建议内容。</p><p><strong>重要性标记</strong>：</p><ul><li>🔴🔴🔴 最关键</li><li>🔴🔴 重要</li><li>🔴 值得考虑</li></ul><hr><h2 id="四、📋-行动计划-三级火箭" tabindex="-1">四、📋 行动计划（三级火箭） <a class="header-anchor" href="#四、📋-行动计划-三级火箭" aria-label="Permalink to &quot;四、📋 行动计划（三级火箭）&quot;">​</a></h2><h3 id="短期实验-1-2周" tabindex="-1">短期实验（1-2周） <a class="header-anchor" href="#短期实验-1-2周" aria-label="Permalink to &quot;短期实验（1-2周）&quot;">​</a></h3><p>一个可以立即开始的&quot;最小可行性改变&quot;：</p><ul><li>[ ] 具体可执行动作</li></ul><h3 id="中期植入-1-3个月" tabindex="-1">中期植入（1-3个月） <a class="header-anchor" href="#中期植入-1-3个月" aria-label="Permalink to &quot;中期植入（1-3个月）&quot;">​</a></h3><p>一个需要持续跟进的新规则或流程：</p><ul><li>[ ] 具体可执行动作</li></ul><h3 id="长期重塑-1年以上" tabindex="-1">长期重塑（1年以上） <a class="header-anchor" href="#长期重塑-1年以上" aria-label="Permalink to &quot;长期重塑（1年以上）&quot;">​</a></h3><p>对底层心智模式或人生战略的启示：</p><ul><li>[ ] 具体可执行动作</li></ul><hr><h2 id="五、🔗-跨界联想与质疑" tabindex="-1">五、🔗 跨界联想与质疑 <a class="header-anchor" href="#五、🔗-跨界联想与质疑" aria-label="Permalink to &quot;五、🔗 跨界联想与质疑&quot;">​</a></h2><h3 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h3><p>这本书让我联想到哪本书？两者是互补还是冲突？</p><h3 id="高阶批判" tabindex="-1">高阶批判 <a class="header-anchor" href="#高阶批判" aria-label="Permalink to &quot;高阶批判&quot;">​</a></h3><p>如果你是作者，在2026年的AI时代，你会对书中哪个观点进行修正或补充？</p><hr><h2 id="六、📖-精彩摘录" tabindex="-1">六、📖 精彩摘录 <a class="header-anchor" href="#六、📖-精彩摘录" aria-label="Permalink to &quot;六、📖 精彩摘录&quot;">​</a></h2><blockquote><p>&quot;金句1&quot;</p></blockquote><blockquote><p>&quot;金句2&quot;</p></blockquote><blockquote><p>&quot;金句3&quot;</p></blockquote><hr><h2 id="分类体系" tabindex="-1">分类体系 <a class="header-anchor" href="#分类体系" aria-label="Permalink to &quot;分类体系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>内容范围</th><th>示例书籍</th></tr></thead><tbody><tr><td>💰 投资理财</td><td>投资策略、财富管理、金融理论</td><td>聪明的投资者、穷查理宝典</td></tr><tr><td>🧠 认知心理学</td><td>思维模式、认知偏差、行为心理学</td><td>思考快与慢、影响力</td></tr><tr><td>📚 哲学思想</td><td>哲学经典、思想启蒙、人生智慧</td><td>沉思录、苏菲的世界、中国哲学简史</td></tr><tr><td>📊 经济社会科学</td><td>经济理论、社会学、政治学、传播学</td><td>置身事内、舆论、小镇喧嚣</td></tr><tr><td>🏠 人性与家庭</td><td>人性分析、家庭教育、家庭关系</td><td>人性论、顶尖家族智慧</td></tr><tr><td>💼 职场发展</td><td>工作方法论、职业素养、管理技巧</td><td>干法、复盘、麦肯锡精英</td></tr></tbody></table><hr><h2 id="用户背景-每次解读自动注入" tabindex="-1">用户背景（每次解读自动注入） <a class="header-anchor" href="#用户背景-每次解读自动注入" aria-label="Permalink to &quot;用户背景（每次解读自动注入）&quot;">​</a></h2><ul><li>17年软件开发经验，做过技术总监、项目管理、部门经理</li><li>带过20+人项目和30+人部门</li><li>两个孩子父亲（三年级女儿面临&quot;畏难&quot;和&quot;人际关系&quot;挑战）</li><li>因家庭和个人身体精力原因，想了解其他行业或寻求改变</li><li>读书笔记需以此背景为基</li></ul>`,98)])])}const c=t(l,[["render",i]]);export{q as __pageData,c as default};
